const stage = document.getElementById("stage");
const scene = document.getElementById("scene");
const answerEl = document.getElementById("answer");
const answerBox = document.getElementById("answerBox");
const resetBtn = document.getElementById("resetBtn");
const enterBtn = document.getElementById("enterBtn");
const intro = document.getElementById("intro");
const consultBtn = document.getElementById("consultBtn");
const quote = document.getElementById("quote");
const logo = document.getElementById("logo");
const descEl = document.querySelector(".description");

const startSrc = scene.src;
const startAlt = scene.alt;

// 답변 화면: 두 사진이 번갈아 나옴
const rooms = [
    { src: "data:image/jpeg;base64,", alt: "거실 소파에 앉아 있는 세 사람과 큰 개" },
    { src: "data:image/jpeg;base64,", alt: "거실에 둘러앉은 세 사람과 큰 개" }
];

const consultSrc = "data:image/jpeg;base64,";

let roomIndex = 0;
let lastAnswer = -1;

function showScene(src, alt) {
    scene.classList.remove("scene-in");
    void scene.offsetWidth;
    scene.src = src;
    scene.alt = alt;
    scene.classList.add("scene-in");
}

function enterShop() {
    let i;
    do {
        i = Math.floor(Math.random() * answers.length);
    } while (answers.length > 1 && i === lastAnswer);
    lastAnswer = i;

    const text = answers[i];
    answerEl.textContent = text;
    answerBox.classList.toggle("long", text.length > 60);

    const room = rooms[roomIndex];
    showScene(room.src, room.alt);
    roomIndex = (roomIndex + 1) % rooms.length;

    stage.classList.add("answering");
    resetBtn.classList.remove("hidden");
    consultBtn.classList.remove("hidden");
    enterBtn.classList.add("gone");
    intro.classList.add("gone");
    resetBtn.focus({ preventScroll: true });
}

function goStart() {
    showScene(startSrc, startAlt);
    stage.classList.remove("answering");
    resetBtn.classList.add("hidden");
    resetBtn.classList.remove("gone");
    consultBtn.classList.add("hidden");
    consultBtn.classList.remove("gone");
    descEl.classList.remove("gone");
    quote.classList.add("gone");
    logo.classList.add("gone");
    enterBtn.classList.remove("gone");
    intro.classList.remove("gone");
    enterBtn.focus({ preventScroll: true });
}

function goConsult() {
    showScene(consultSrc, "고민 해결 청구 비용을 종이에 적어 보여주는 모습");
    stage.classList.remove("answering");

    // 버튼과 안내 문구는 모두 없애고 made by K만 남김
    enterBtn.classList.add("gone");
    intro.classList.add("gone");
    resetBtn.classList.add("gone");
    consultBtn.classList.add("gone");
    descEl.classList.add("gone");

    quote.classList.remove("gone");
    logo.classList.remove("gone");
}
